# -*- coding: utf-8 -*-
from wid_h import *
W={}
W['upper']={'LCL':calc('A rising air parcel cools until it reaches its dew point. Clouds begin there.',[P('t','Surface temperature',10,40,1,28,' °C'),P('td','Surface dew point',0,35,1,16,' °C')],[O('Cloud base (LCL)','125*(t-td)',5000,' m',0)],eq='LCL ≈ 125 m × (T − Td)',note='<b>{=125*(t-td)|0}</b> m. A bigger gap between T and Td means a higher cloud base.',pre=('Dry air (dew point far below the temperature) makes cloud bases that are…',['Lower','Higher'],1,'A big T − Td gap means air must rise farther before it saturates.')),
'Inversion':plot('Normally air cools with height. An inversion is a warm layer above cooler air.',['t0-6.5*x','t0-6.5*x+inv*min(1,max(0,x-1))'],[P('t0','Surface temp',0,35,1,20,' °C'),P('inv','Warm layer',0,10,1,5)],x=(0,6),y=(-20,40),out='Surface {t0} °C. Normal cooling is about 6.5 °C per km.',xl='height (km)',yl='°C')}
W['setup']={'Wind shear':simple('steps','Wind that changes with height tilts and twists storms.',s=[dict(t='Imagine wind near the ground blowing slowly from the east.'),dict(t='Higher up, the wind blows fast from the west.'),dict(t='That change with height is wind shear. A rising updraft gets tilted and twists, so it can spin into a rotating storm.')],take='Shear + instability + moisture + a trigger = severe storms.')}
W['tstorm']={'Life cycle':simple('steps','Follow a thunderstorm from birth to death.',s=[dict(t='Cumulus stage: warm air rises in an updraft. Clouds grow upward.'),dict(t='Mature stage: rain and hail fall, creating a downdraft beside the updraft. This is the strongest stage.'),dict(t='Dissipating: the downdraft cuts off the warm updraft. The storm weakens and rains out.')],take='A storm dies when its own cold downdraft cuts off the updraft.')}
W['hurr']={'Saffir-Simpson':calc('Hurricane category by sustained wind.',[P('w','Wind speed',74,180,2,100,' mph')],[O('Category','w>=157?5:0',5,'',0)],eq='')}
del W['hurr']
W['obs']={'Ground tools':simple('steps','What each weather tool measures.',s=[dict(t='Thermometer: air temperature.'),dict(t='Barometer: air pressure. Falling pressure often means a storm is coming.'),dict(t='Anemometer: wind speed. Wind vane: wind direction.'),dict(t='Hygrometer: humidity. Rain gauge: rainfall.')])}
W['maps']={'Wind barb':dict(k='steps',hook='Read a wind barb.',s=[dict(t='The staff points from the direction the wind comes FROM.'),dict(t='A short line (half barb) = 5 knots. A long line = 10 knots. A flag (triangle) = 50 knots.'),dict(t='Add them up. One long + one short = 15 knots.')])}
W['precip']={'Warm rain':dict(k='steps',hook='How a raindrop forms.',s=[dict(t='Water vapor condenses onto tiny particles, making cloud droplets.'),dict(t='Bigger droplets fall faster and collide with smaller ones.'),dict(t='Droplets merge (coalescence) until they are heavy enough to fall as rain.')])}
W['dh']={'Heat wave':dict(k='steps',hook='Why heat waves last.',s=[dict(t='A strong high-pressure system parks over a region.'),dict(t='Sinking air under the high warms and clears skies.'),dict(t='Sunshine heats the ground all day and the heat builds for days.')])}
W['light']={'How clouds charge':dict(k='steps',hook='How lightning charge builds up.',s=[dict(t='Ice crystals and hail collide inside the storm.'),dict(t='Heavier particles gain negative charge and sink; lighter ones gain positive and rise.'),dict(t='Charges separate. Lightning is the spark that rebalances them.')])}
W['torn']={'EF scale':calc('The Enhanced Fujita scale rates damage, not size.',[P('w','Estimated wind',65,200,5,100,' mph')],[O('Wind','w',200,' mph',0)],note='EF0: 65–85 mph · EF1: 86–110 · EF2: 111–135 · EF3: 136–165 · EF4: 166–200 · EF5: over 200.')}
W['winds']={'Downburst':dict(k='steps',hook='A downburst is a column of sinking air.',s=[dict(t='Rain and hail drag air downward.'),dict(t='Air hits the ground and spreads out in all directions.'),dict(t='The spreading air causes damaging straight-line winds.')])}
WID=W
